// Verify HMAC-SHA256 signature from TeamRetro.
// Store your webhook signing secret in an n8n credential or env variable.
// Header format: X-TeamRetro-Signature: t=<unixTs>,v1=<hexHmac>
// Signed input: "<unixTs>.<rawBody>"
// CRITICAL: "Raw Body" must be enabled on the Webhook node. Re-serializing JSON.stringify(body) will NOT match.
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto in your n8n environment.

const crypto = require('crypto');

const item = $input.first();
const sigHeader = item.json.headers['x-teamretro-signature'] ?? '';
// With "Raw Body" enabled, the raw bytes arrive as base64 in binary.data.data:
const rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
const secret  = 'REPLACE_WITH_YOUR_SIGNING_SECRET';

const parts = Object.fromEntries(sigHeader.split(',').map((p) => p.split('=')));

if (!parts.t || !parts.v1) {
  throw new Error('Missing X-TeamRetro-Signature header');
}

const expected = crypto
  .createHmac('sha256', secret)
  .update(`${parts.t}.${rawBody}`)
  .digest('hex');
const received = Buffer.from(parts.v1, 'hex');

if (received.length !== 32 || !crypto.timingSafeEqual(received, Buffer.from(expected, 'hex'))) {
  throw new Error('Invalid TeamRetro signature — request rejected');
}

return $input.all();
